#include <stdio.h>
#include <ctype.h>

int main(void) {
    int n, found = 0;
    scanf("%d", &n);
    for (int i = 0; i < n; i++) {
        char name[64];
        scanf("%63s", name);
        FILE *f = fopen(name, "r");
        if (f == NULL) {
            printf("%s: missing\n", name);
            continue;
        }
        found++;
        int c, last = '\n', lines = 0, words = 0, in_word = 0;
        while ((c = fgetc(f)) != EOF) {
            if (c == '\n') lines++;
            if (isspace(c)) {
                in_word = 0;
            } else if (!in_word) {
                in_word = 1;
                words++;
            }
            last = c;
        }
        if (last != '\n') lines++;
        fclose(f);
        printf("%s: %d lines, %d words\n", name, lines, words);
    }
    printf("found %d of %d files\n", found, n);
    return 0;
}
